### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<string> g(n);
    for (int i = 0; i < n; ++i) cin >> g[i];

    auto idx = [&](int r, int c) { return r * n + c; };
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    vector<char> visX(n * n, 0);
    vector<int> mark(n * n, -1);
    unordered_map<int, int> capture;
    int gid = 0;

    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < n; ++c) {
            if (g[r][c] != 'x') continue;
            int id = idx(r, c);
            if (visX[id]) continue;

            gid++;
            queue<pair<int, int>> q;
            q.push({r, c});
            visX[id] = 1;
            int size = 0;
            int libCount = 0;
            int lastLib = -1;

            while (!q.empty()) {
                auto [ur, uc] = q.front(); q.pop();
                size++;
                for (int k = 0; k < 4; ++k) {
                    int vr = ur + dr[k], vc = uc + dc[k];
                    if (vr < 0 || vr >= n || vc < 0 || vc >= n) continue;
                    char ch = g[vr][vc];
                    if (ch == 'x') {
                        int nid = idx(vr, vc);
                        if (!visX[nid]) {
                            visX[nid] = 1;
                            q.push({vr, vc});
                        }
                    } else if (ch == '.') {
                        int e = idx(vr, vc);
                        if (mark[e] != gid) {
                            mark[e] = gid;
                            libCount++;
                            lastLib = e;
                        }
                    }
                    // 'o' 忽略
                }
            }

            if (libCount == 1) {
                capture[lastLib] += size;
            }
        }
    }

    vector<tuple<int, int, int>> ans;
    ans.reserve(capture.size());
    for (auto &kv : capture) {
        int e = kv.first, cnt = kv.second;
        int r = e / n, c = e % n;
        ans.push_back({r + 1, c + 1, cnt});
    }
    sort(ans.begin(), ans.end());

    cout << ans.size() << "\n";
    for (auto &t : ans) {
        int a, b, cnt;
        tie(a, b, cnt) = t;
        cout << a << ' ' << b << ' ' << cnt << "\n";
    }
    return 0;
}
